from itertools import permutations

historians = ("Farley", "Garcia", "Holden", "Jiang")
topics = ("lithographs", "oil paintings", "sculptures", "watercolors")
valid = []

for people_order in permutations(historians):
    p = {name: i for i, name in enumerate(people_order)}
    if not (p["Holden"] < p["Garcia"] and p["Holden"] < p["Jiang"]):
        continue
    for topic_order in permutations(topics):
        t = {topic: i for i, topic in enumerate(topic_order)}
        if not (
            t["oil paintings"] < t["lithographs"]
            and t["watercolors"] < t["lithographs"]
            and p["Farley"] < t["oil paintings"]
        ):
            continue
        truths = {
            "A": p["Farley"] < t["sculptures"],
            "B": p["Holden"] < t["lithographs"],
            "C": t["sculptures"] < p["Garcia"],
            "D": t["sculptures"] < p["Jiang"],
            "E": t["watercolors"] < p["Garcia"],
        }
        valid.append((people_order, topic_order, truths))

print("Exhaustively checked all", 24 * 24, "possible schedules.")
print("Valid schedules:", len(valid))

if not valid:
    print("CHECK UNKNOWN: constraints have no valid schedule.")
else:
    must_be_true = []
    for option in "ABCDE":
        count = sum(truths[option] for _, _, truths in valid)
        print(f"{option}: true in {count}/{len(valid)} valid schedules")
        if count == len(valid):
            must_be_true.append(option)

    print("Options that must be true:", ", ".join(must_be_true) or "none")
    submitted = "D"
    counterexample = next(
        (schedule for schedule in valid if not schedule[2][submitted]),
        None,
    )
    if counterexample is not None:
        people_order, topic_order, _ = counterexample
        print("Counterexample to submitted answer D:")
        for slot, (person, topic) in enumerate(
            zip(people_order, topic_order), start=1
        ):
            print(f"  {slot}: {person} — {topic}")
    print("CHECK PASS" if must_be_true == [submitted] else "CHECK FAIL")
